import type { EntityInput, TechnologyInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";

/**
 * Recovery and rejuvenation, body system by body system: what cancer treatment takes, and whether it comes back.
 *
 * The question a person finishing treatment asks is not "what is this called" but "will it come back, and when".
 * Almost nothing written for patients answers it, so every record here states plainly whether recovery is usual,
 * partial or unlikely, over what timescale, and from which source. Where the answer is "we do not know", it says so.
 *
 * Each approach carries an honest grade as a tag `evidence:<grade>`, the same model as src/data/complementary.ts
 * and src/lib/complementary.ts: strong = consistent randomised trials plus a major guideline recommendation;
 * moderate = trials exist but small, mixed or single-setting; insufficient = no reliable human evidence of benefit;
 * no-benefit = adequately sized trials found nothing; harm = toxicity, interaction, or use in place of standard
 * treatment. A number appears only where the linked primary source states it, and every figure here was read from
 * the abstract or full text of the paper cited beside it, not from memory.
 *
 * Records the corpus already held are supplemented in place rather than duplicated: `exercise-oncology`,
 * `structured-exercise-survivorship`, `exercise-during-chemotherapy`, `resistance-training-cachexia`,
 * `prehabilitation`, `fertility-preservation`, `bone-modifying-agents`, `cardio-oncology`,
 * `lymphoedema-decongestive-therapy`, `photobiomodulation-mucositis`, `frozen-gloves-compression-taxane` and
 * `survivorship-care-plan` each gain the `rejuvenation` front in their own file.
 *
 * Hair is covered elsewhere in this round; biological ageing and the frontier are too. This file is the body.
 * UK spelling.
 *
 * The `rejuvenation` section record itself is written alongside this file in the same round and is not defined here.
 * Until it lands, every `sections: ["rejuvenation"]` below is a reference with nothing to resolve to, so this module
 * is merged together with the one that defines the front rather than on its own.
 */

const asOf = "2026-10-02";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

const REJ = "rejuvenation";
const SUP = "supportive-care";

const T = (grade: EvidenceGrade, extra: string[] = []) => ["rejuvenation", "survivorship", `evidence:${grade}`, ...extra];
const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });

// Sources used by more than one record.
