const ASCO_EXERCISE_2022 = doi("Exercise, Diet, and Weight Management During Cancer Treatment: ASCO Guideline (JCO 2022)", "10.1200/JCO.22.00687");
const CHALLENGE_2025 = doi("CHALLENGE: structured exercise after adjuvant chemotherapy for colon cancer (NEJM 2025)", "10.1056/NEJMoa2502760");
const ASCO_BONE_2019 = doi("Management of Osteoporosis in Survivors of Adult Cancers With Nonmetastatic Disease: ASCO guideline (JCO 2019)", "10.1200/JCO.19.01696");
const ESC_CARDIO_2022 = doi("2022 ESC Guidelines on cardio-oncology (Eur Heart J 2022)", "10.1093/eurheartj/ehac244");
const ASCO_CARDIAC_2017 = doi("Prevention and Monitoring of Cardiac Dysfunction in Survivors of Adult Cancers: ASCO guideline (JCO 2017)", "10.1200/JCO.2016.70.5400");
const ASCO_CIPN_2020 = doi("Prevention and Management of Chemotherapy-Induced Peripheral Neuropathy in Survivors of Adult Cancers: ASCO Guideline Update (JCO 2020)", "10.1200/JCO.20.01399");
const ASCO_FERTILITY_2018 = doi("Fertility Preservation in Patients With Cancer: ASCO guideline update (JCO 2018)", "10.1200/JCO.2018.78.1914");
const ASCO_SEXUAL_2018 = doi("Interventions to Address Sexual Problems in People With Cancer: ASCO guideline adaptation (JCO 2018)", "10.1200/JCO.2017.75.8995");
