const heart: TechnologyInput[] = [
  tech({ id: "cardiotoxicity-surveillance-recovery", name: "Heart function after anthracyclines, trastuzumab and chest radiotherapy", sections: [REJ, SUP, "chemotherapy"], status: "standard-of-care", wikipedia: W("Cardio-oncology"), tags: T("strong"),
    tldr: "Most heart damage from anthracycline chemotherapy appears within the first year after it finishes, and most of it improves at least partly when it is caught and treated. Heart muscle weakened by trastuzumab usually recovers when the drug is stopped. Radiotherapy to the chest raises the risk of coronary disease years later, in proportion to the dose the heart received.",
    summary: "The best single description of anthracycline cardiotoxicity comes from a cohort of 2,625 patients whose ejection fraction was measured before treatment, every three months during it and for a year afterwards, then twice yearly. Cardiotoxicity, defined as a fall in ejection fraction of more than ten absolute points to below 50 per cent, occurred in 9 per cent. The median time from the end of chemotherapy was 3.5 months, and 98 per cent of cases appeared within the first year. Everyone affected was started on heart failure treatment: 11 per cent recovered fully to their baseline ejection fraction and most of the rest recovered partly. That reframes the old idea of late-onset damage appearing out of nowhere decades later: the first year is when to look.\n\nTrastuzumab is a different and gentler picture. In the HERA trial, one year of trastuzumab after anthracycline chemotherapy caused severe heart failure in 0.8 per cent against none in the observation arm, and a confirmed significant fall in ejection fraction in 3.6 per cent against 0.6 per cent. Of the 73 patients in the trastuzumab arm who reached a cardiac endpoint, 59 reached acute recovery.\n\nRadiotherapy is slower. In a case-control study of 2,168 women treated in Sweden and Denmark between 1958 and 2001, the rate of major coronary events rose by 7.4 per cent for every gray of mean heart dose, with no apparent threshold, starting within five years and continuing into the third decade. Those women were treated with older techniques and received an average mean heart dose of 4.9 gray; breath-hold, prone positioning and modern planning have cut cardiac doses substantially since, so the risk per patient today is lower while the dose-response relationship still holds.\n\nWho is watched, and how. ASCO's 2017 guideline says the threshold for cardiac evaluation should be low in anyone who received potentially cardiotoxic therapy, that higher-risk survivors may benefit from prevention and screening during treatment, and that routine imaging surveillance after treatment may be warranted for higher-risk survivors so that progression can be halted or reversed. The 2022 European Society of Cardiology guideline, the first devoted to cardio-oncology, is the reference for baseline risk stratification and the surveillance schedule. Echocardiography with global longitudinal strain detects dysfunction earlier than ejection fraction, and troponin rises before either.\n\nWhat comes back, and when: usually partial, sometimes complete, and the timing favours the watchful. For anthracyclines, 11 per cent of those affected returned fully to baseline and most of the rest improved, with treatment started promptly. For trastuzumab, recovery after stopping is the usual outcome. For radiation coronary disease, nothing reverses, which is why the lever is the dose at planning rather than anything done afterwards.",
    principle: "Anthracyclines damage cardiomyocytes through topoisomerase-2-beta-mediated DNA damage and oxidative stress, causing cell loss that is largely irreversible once established but partly compensated if heart failure treatment starts early. Trastuzumab blocks HER2 signalling that cardiomyocytes use for repair, which is why its effect is usually reversible on withdrawal. Radiation injures the coronary microvasculature and endothelium, producing accelerated atherosclerosis years later.",
    strengths: ["The window to find anthracycline damage is defined: the first year after treatment", "Trastuzumab-related dysfunction usually recovers when the drug stops", "Strain imaging and troponin detect injury before the ejection fraction falls"],
    limitations: ["Surveillance is patchy outside large centres, and survivorship plans rarely name who does it", "Radiation coronary disease does not reverse", "The dose-response figure comes from cohorts treated with older, higher-dose techniques"],
    cancers: ["breast-her2-positive", "breast-hr-positive", "dlbcl", "hodgkin-lymphoma", "sarcoma"], drugs: ["doxorubicin", "trastuzumab", "epirubicin"], technologies: ["cardio-oncology", "cardiac-biomarker-monitoring", "strain-echocardiography-gls", "survivorship-care-plan", "anthracycline-cardioprotection", "imrt-igrt"], terms: ["trastuzumab-cardiotoxicity", "late-effects"], bottlenecks: ["b-survivorship", "b-toxicity-qol"], related: ["idea-moon-cardioprotection-by-default"],
    links: [doi("Early detection of anthracycline cardiotoxicity and improvement with heart failure therapy (Circulation 2015)", "10.1161/CIRCULATIONAHA.114.013777"), doi("Longer-term assessment of trastuzumab-related cardiac adverse events in the HERA trial (JCO 2010)", "10.1200/JCO.2009.26.0463"), doi("Risk of ischemic heart disease in women after radiotherapy for breast cancer (NEJM 2013)", "10.1056/NEJMoa1209825"), ASCO_CARDIAC_2017, ESC_CARDIO_2022] }),

  tech({ id: "anthracycline-cardioprotection", name: "Protecting the heart during anthracycline treatment: dexrazoxane, beta blockers and ACE inhibitors", sections: [REJ, SUP, "chemotherapy"], status: "established", wikipedia: W("Dexrazoxane"), tags: T("moderate"),
    tldr: "Dexrazoxane, given with the chemotherapy, cuts clinical heart failure in adults by about four fifths in pooled trials without reducing how well the chemotherapy works. Beta blockers and blood-pressure drugs given preventively protect the ejection fraction by a point or two during treatment, and in the one trial that followed patients for two years that difference had gone.",
    summary: "Dexrazoxane is the cardioprotectant with the strongest evidence. The 2022 Cochrane review of 13 randomised trials found that in adults it reduced clinical heart failure with a risk ratio of 0.22 (95 per cent confidence interval 0.11 to 0.43, seven studies, 1,221 adults, moderate-quality evidence), with similar benefits on combined subclinical and clinical dysfunction and no difference in overall survival. In children the evidence was weaker and the review could not pool it. The historical worry that dexrazoxane blunted tumour response or caused second cancers has not been borne out in the survival data, but it remains restricted in label and in practice to patients receiving high cumulative anthracycline doses.\n\nNeurohormonal prevention is the approach that looked promising and then shrank. In PRADA, 130 women with early breast cancer received candesartan, metoprolol, both or placebo alongside anthracycline-containing adjuvant therapy. The ejection fraction fell 2.6 percentage points on placebo and 0.8 on candesartan, a difference of 1.8 points. Metoprolol had no effect on ejection fraction. At extended follow-up a median of 23 months after randomisation, there were no significant between-group differences, and the authors concluded that \"a broadly administered cardioprotective approach may not be required in most patients with early breast cancer without preexisting cardiovascular disease\". Candesartan did preserve global longitudinal strain and left ventricular volume modestly at two years.\n\nThe other levers are structural rather than pharmacological: capping the cumulative anthracycline dose, continuous rather than bolus infusion, liposomal formulations, and sparing the heart at radiotherapy planning. Treating conventional cardiovascular risk, which is the single largest determinant of whether a survivor develops heart failure, is the part most often skipped.\n\nWhat comes back, and when: this record is about damage not happening rather than damage reversing. Where prevention is used, it works during the treatment window; where it is not, the recovery figures are the ones in the surveillance record alongside this one.",
    principle: "Dexrazoxane chelates iron and interferes with the topoisomerase-2-beta complex through which anthracyclines damage cardiomyocytes. Angiotensin blockade and beta blockade act on the neurohormonal response to injury rather than on the injury itself, which is consistent with their effect being small and not sustained after the drugs stop.",
    strengths: ["Pooled randomised evidence for dexrazoxane in adults with no survival penalty", "Dose capping, infusion schedule and liposomal formulation reduce exposure directly", "Treating ordinary cardiovascular risk is cheap and under-used"],
    limitations: ["Candesartan and metoprolol gave no sustained benefit at two years in the only trial to look", "Dexrazoxane evidence in children is weak and unpooled", "Restricted use means most adults receiving anthracyclines never see it"],
    cancers: ["breast-her2-positive", "breast-hr-positive", "dlbcl", "sarcoma", "all-leukemia"], drugs: ["dexrazoxane", "doxorubicin", "epirubicin", "trastuzumab", "pegylated-liposomal-doxorubicin"], technologies: ["cardio-oncology", "cardiotoxicity-surveillance-recovery", "cardiac-biomarker-monitoring"], terms: ["trastuzumab-cardiotoxicity", "late-effects"], bottlenecks: ["b-toxicity-qol"], related: ["idea-moon-cardioprotection-by-default"],
    links: [doi("Dexrazoxane for preventing or reducing cardiotoxicity in adults and children with cancer receiving anthracyclines (Cochrane 2022)", "10.1002/14651858.CD014638.pub2"), doi("PRADA: candesartan and metoprolol during adjuvant breast cancer therapy (Eur Heart J 2016)", "10.1093/eurheartj/ehw022"), doi("PRADA extended follow-up (Circulation 2021)", "10.1161/CIRCULATIONAHA.121.054698"), ESC_CARDIO_2022] }),
];

