const nerves: TechnologyInput[] = [
  tech({ id: "cipn-recovery-and-treatment", name: "Nerve damage from chemotherapy: what recovers, and what helps", sections: [REJ, SUP, "chemotherapy"], status: "established", wikipedia: W("Chemotherapy-induced_peripheral_neuropathy"), tags: T("moderate"),
    tldr: "Numbness, tingling and pain in the hands and feet are common on platinum, taxane, vinca and proteasome-inhibitor treatment, and most of it fades. In a meta-analysis of 4,179 patients it was present in 68 per cent in the first month, 60 per cent at three months and 30 per cent at six months or later. Only duloxetine has evidence for the pain, and no drug prevents it.",
    summary: "The drugs that cause it are the platinums (oxaliplatin and cisplatin), the taxanes (paclitaxel, docetaxel, nab-paclitaxel), the vinca alkaloids (vincristine), bortezomib and thalidomide. Oxaliplatin adds a cold-triggered acute form during and just after each infusion, and can go on worsening for weeks after the last dose.\n\nThe timescale is the figure most often missing from patient information. A systematic review of 31 studies and 4,179 patients found prevalence of 68.1 per cent (57.7 to 78.4) when measured in the first month after chemotherapy, 60.0 per cent (36.4 to 81.6) at three months, and 30.0 per cent (6.4 to 53.5) at six months or more. The authors' own conclusion is the honest sentence to give a reader: \"Although CIPN prevalence decreases with time, at 6months 30% of patients continue to suffer from CIPN.\"\n\nWhat helps. ASCO's 2020 guideline update is blunt: \"no agents are recommended for the prevention of CIPN\", acetyl-L-carnitine \"should be discouraged\" because a trial found it made neuropathy worse, and \"Duloxetine is the only agent that has appropriate evidence to support its use for patients with established painful CIPN. Nonetheless, the amount of benefit from duloxetine is limited.\" The trial behind that recommendation randomised 231 patients to duloxetine 60 mg daily or placebo for five weeks: average pain fell 1.06 points on a 0 to 10 scale against 0.34 on placebo, a difference of 0.73 (95 per cent confidence interval 0.26 to 1.20), and 59 per cent of those on duloxetine reported some decrease in pain against 38 per cent on placebo.\n\nThe things with the most promise are physical rather than pharmacological, and they are given during the infusion rather than afterwards: cooling and compression of the hands and feet during taxane treatment. These have their own record in the corpus. Dose reduction, delay or substitution remains the single most effective response to neuropathy that is becoming disabling, and ASCO explicitly tells clinicians to assess whether it is appropriate.\n\nA long list has been tried and failed or has no reliable evidence: acetyl-L-carnitine (discouraged), vitamin E, glutamine, calcium and magnesium infusions, amifostine, alpha-lipoic acid, gabapentin, pregabalin and topical amitriptyline-ketamine. Acupuncture and scrambler therapy are covered separately and neither has convincing sham-controlled evidence.\n\nWhat comes back, and when: partial, and mostly in the first six months. Two thirds of people have recovered by six months; about a third have symptoms that persist beyond that, and for those the evidence is about managing pain rather than restoring the nerve. Numbness responds less well than pain. Balance and falls are the part most worth treating with physiotherapy, because the risk is a fracture.",
    principle: "Platinums damage dorsal root ganglion cell bodies through DNA adduct formation, taxanes and vincas disrupt axonal microtubule transport, and bortezomib affects mitochondrial and endoplasmic reticulum function in sensory neurons. Because the injury is to the longest axons and sometimes the cell body itself, recovery depends on axonal regrowth at roughly a millimetre a day and is incomplete where the neuron has died.",
    strengths: ["The recovery curve is known and can be told to a patient honestly", "Duloxetine has a randomised, placebo-controlled basis for established painful neuropathy", "Dose modification works and is always available"],
    limitations: ["Nothing prevents it: ASCO recommends no preventive agent", "Duloxetine's benefit is small and the guideline says so", "Numbness and loss of balance respond less than pain"],
    cancers: ["colorectal", "breast-hr-positive", "multiple-myeloma", "ovarian", "nsclc", "testicular"], drugs: ["oxaliplatin", "cisplatin", "paclitaxel", "docetaxel", "vincristine", "bortezomib", "thalidomide"], technologies: ["frozen-gloves-compression-taxane", "acupuncture-chemotherapy-neuropathy", "scrambler-therapy", "survivorship-care-plan", "exercise-prescription-after-cancer", "glutamine-mucositis-neuropathy"], terms: ["peripheral-neuropathy", "late-effects"], bottlenecks: ["b-toxicity-qol", "b-survivorship"], related: ["idea-moon-neuropathy-prevention-programme"],
    links: [ASCO_CIPN_2020, doi("Incidence, prevalence, and predictors of chemotherapy-induced peripheral neuropathy: systematic review and meta-analysis (Pain 2014)", "10.1016/j.pain.2014.09.020"), doi("Effect of duloxetine on pain, function, and quality of life among patients with chemotherapy-induced painful peripheral neuropathy (JAMA 2013)", "10.1001/jama.2013.2813"), doi("POLAR: hand cooling and compression to prevent taxane-induced neuropathy (JAMA Oncol 2025)", "10.1001/jamaoncol.2025.0001")] }),

  tech({ id: "scrambler-therapy", name: "Scrambler therapy (Calmare) for chemotherapy nerve pain", sections: [REJ, SUP, "devices"], status: "emerging", wikipedia: W("Transcutaneous_electrical_nerve_stimulation"), tags: T("insufficient"),
    tldr: "A surface electrical device that is said to replace pain signals with signals the brain reads as normal. People treated with it often feel better, but in the only trial that compared it with a dummy device there was no difference between the two, so what is being felt may be the attention and the expectation rather than the machine.",
    summary: "Scrambler therapy, marketed as Calmare, applies low-intensity electrical stimulation through surface electrodes placed around the painful area, usually in ten daily sessions. The claim is that it substitutes synthetic non-pain information for the pain signal travelling in the same C-fibre pathway.\n\nThe open-label evidence is encouraging and the controlled evidence is not. In a randomised phase 2 trial of 50 patients comparing scrambler therapy with transcutaneous electrical nerve stimulation, \"twice as many Scrambler-treated patients who had at least a 50% documented improvement during the 2 treatment weeks, from their baseline pain, tingling, and numbness scores, when compared with the TENS-treated patients (from 36 to 56% compared with 16-28% for each symptom)\". But in the pilot sham-controlled trial, where patients could not tell which device they had, there were \"no significant differences between the sham and the 'real' ST group at day 10, 28, 60, or 90, for average pain\", and the authors wrote: \"We observed no difference between sham and real ST CIPN treatment.\" Notably, \"All 'real' patients wanted to continue treatment if available.\"\n\nA 2026 systematic review of the randomised trials found only two eligible studies, 35 and 50 participants, of low to moderate quality, and concluded that \"Scrambler therapy does not yet meet statistical criteria for a successful treatment CIPN\".\n\nThis is listed here, graded insufficient, because it is sold to people with chemotherapy nerve pain who will otherwise find only the marketing. It is not dangerous, and a larger sham-controlled trial would settle it.\n\nWhat comes back, and when: unknown. No controlled trial has shown a change in nerve function, and the only blinded comparison found the dummy device did as well.",
    principle: "Electrodes placed on intact skin proximal and distal to the painful area deliver patterned low-amplitude current intended to be interpreted centrally as non-painful, on the theory that plastic reorganisation of the pain pathway outlasts the stimulation. The sham comparison is the test of whether that mechanism, rather than expectation, is doing the work.",
    strengths: ["Non-invasive, no drug interactions, no reported serious harms", "Patients in the trials wanted to continue it", "A properly powered sham-controlled trial would be straightforward to run"],
    limitations: ["The only sham-controlled trial found no difference from the dummy device", "Both randomised trials are small and at low to moderate risk of bias", "Ten clinic visits, and usually paid for privately"],
    cancers: ["colorectal", "breast-hr-positive", "multiple-myeloma"], drugs: ["oxaliplatin", "paclitaxel", "bortezomib"], technologies: ["cipn-recovery-and-treatment", "acupuncture-chemotherapy-neuropathy", "pain-management"], terms: ["peripheral-neuropathy", "placebo"], bottlenecks: ["b-toxicity-qol"],
    links: [doi("A pilot randomized sham-controlled trial of MC5-A scrambler therapy in chronic chemotherapy-induced peripheral neuropathy (J Palliat Care 2020)", "10.1177/0825859719827589"), doi("Scrambler therapy for chemotherapy neuropathy: a randomized phase II pilot trial (Support Care Cancer 2020)", "10.1007/s00520-019-04881-3"), doi("Efficacy of scrambler therapy in chemotherapy-induced peripheral neuropathy: a systematic review of randomized controlled trials (J Egypt Natl Canc Inst 2026)", "10.1186/s43046-026-00347-w"), ASCO_CIPN_2020] }),
];

