const surfaces: TechnologyInput[] = [
  tech({ id: "dry-mouth-teeth-after-head-neck-radiotherapy", name: "Dry mouth, teeth and taste after head and neck radiotherapy", sections: [REJ, SUP, "radiation"], status: "standard-of-care", wikipedia: W("Xerostomia"), tags: T("strong"),
    tldr: "Radiotherapy to the head and neck damages the salivary glands and, through the dry mouth that follows, the teeth. Planning that steers dose away from the parotid glands roughly halves lasting dryness and lets saliva recover over a year or two. Teeth need a dental assessment before treatment starts, because extractions afterwards risk the jawbone failing to heal.",
    summary: "Parotid-sparing planning is the intervention that changed this. In the PARSPORT randomised trial, grade 2 or worse dry mouth at 12 months occurred in 38 per cent of patients given intensity-modulated radiotherapy against 74 per cent given conventional radiotherapy, and at 24 months in 29 against 83 per cent. The trial also reported \"significant benefits\" in \"recovery of saliva secretion\" with the modulated technique at both time points, with no difference in locoregional control or survival. Recovery of saliva is therefore not a hope but a measured outcome, and it depends on what the planning did.\n\nWhen dryness persists, pilocarpine is the drug with randomised evidence. In 207 patients who had received at least 4,000 centigray, oral dryness improved in 44 per cent on 5 mg three times daily against 25 per cent on placebo, with overall improvement in 54 against 25 per cent; sweating was the main side effect and 6 per cent of the 5 mg group and 29 per cent of the 10 mg group withdrew because of adverse effects. Amifostine is covered by ASCO's protectants guideline and is little used because of hypotension, nausea and infusion time. Acupuncture for dry mouth has its own record and a weaker evidence base. Saliva substitutes, sugar-free gum and frequent sips help symptoms without restoring gland function.\n\nTeeth are the part that is preventable and most often missed. A dental assessment before radiotherapy, with any doubtful teeth removed while the jaw can still heal, plus lifelong daily high-fluoride toothpaste or trays and regular dental review, is the standard of care. Radiation caries progresses quickly in a dry mouth, and an extraction from an irradiated mandible can trigger osteoradionecrosis, for which hyperbaric oxygen has Cochrane-level moderate evidence.\n\nTaste is the symptom people report most and the one with the least evidence. It changes within the first weeks of treatment and usually improves over the months afterwards, but OnCo has not found a cohort with a recovery curve it can stand behind, and no treatment has reliable randomised support. That gap is stated rather than filled.\n\nWhat comes back, and when: partial, over one to two years, and mostly determined by the radiotherapy plan. Saliva recovers measurably after parotid-sparing treatment and much less after conventional treatment. Teeth do not come back, which is why the dental work belongs before the first fraction.",
    principle: "Serous acinar cells of the parotid are among the most radiosensitive tissues in the body, and mean parotid dose predicts long-term flow. Sparing the contralateral parotid below a threshold dose preserves stimulated flow that recovers over months. Saliva is also the mouth's buffering and remineralising system, so losing it causes a distinctive pattern of caries at the tooth necks, and irradiated bone has reduced vascularity and healing capacity.",
    strengths: ["Randomised evidence that modulated radiotherapy halves lasting dryness and allows saliva recovery", "Pilocarpine has a placebo-controlled trial behind it", "Pre-treatment dental assessment prevents the worst complication"],
    limitations: ["Taste change has no treatment with reliable evidence and no verified recovery curve", "Pilocarpine causes sweating and a substantial minority stop it", "Dental access and funding for lifelong review are inconsistent"],
    cancers: ["head-and-neck", "thyroid"], drugs: ["pilocarpine", "amifostine"], technologies: ["imrt-igrt", "acupuncture-xerostomia", "photobiomodulation-mucositis", "hyperbaric-oxygen-radiation-injury", "survivorship-care-plan", "proton-therapy"], terms: ["mucositis", "late-effects"], bottlenecks: ["b-toxicity-qol", "b-survivorship"], related: ["idea-moon-mucositis-taste-programme"],
    links: [doi("PARSPORT: parotid-sparing intensity modulated versus conventional radiotherapy in head and neck cancer (Lancet Oncol 2011)", "10.1016/S1470-2045(10)70290-4"), doi("Oral pilocarpine for post-irradiation xerostomia in patients with head and neck cancer (NEJM 1993)", "10.1056/NEJM199308053290603"), doi("ASCO 2008 clinical practice guideline update: use of chemotherapy and radiation therapy protectants (JCO 2009)", "10.1200/JCO.2008.17.2627")] }),

  tech({ id: "bowel-after-pelvic-radiotherapy", name: "Bowel function after pelvic radiotherapy", sections: [REJ, SUP, "radiation"], status: "established", wikipedia: W("Radiation_proctitis"), tags: T("moderate"),
    tldr: "New bowel symptoms after radiotherapy to the prostate, cervix, womb, bladder or rectum are common and are often treated as something to live with. They usually have several separate and treatable causes, and a trial showed that working through them with a written algorithm, delivered by a nurse or a gastroenterologist, improved symptoms more than a self-help booklet.",
    summary: "The condition has a name, pelvic radiation disease, proposed in 2010 so that the whole picture could be studied rather than its parts. The 2011 British Society of Gastroenterology practice guidance states that \"the largest group of patients affected by chronic GI symptoms are those who have been treated with pelvic radiotherapy\" and that \"their complex symptoms, often caused by more than one diagnosis, need systematic investigation by gastroenterologists when empirical treatments fail\".\n\nThe separate diagnoses that hide inside \"radiation bowel damage\" include bile acid malabsorption, small intestinal bacterial overgrowth, pancreatic insufficiency, lactose intolerance, anal sphincter weakness, rectal bleeding from radiation telangiectasia and, importantly, a new unrelated bowel disease. Each has a different treatment, which is why a systematic work-up outperforms empirical anti-diarrhoeals.\n\nThe ORBIT trial randomised 218 patients with new gastrointestinal symptoms persisting six months after pelvic radiotherapy to a detailed self-help booklet, gastroenterologist-led algorithm-based treatment, or nurse-led algorithm-based treatment. At six months the mean difference in bowel symptom score was 4.12 for nurse-led care against the booklet (95 per cent confidence interval 0.04 to 8.19) and 5.47 for gastroenterologist-led care (1.14 to 9.81), and the nurse-led arm was not inferior to the gastroenterologist-led arm. The authors concluded that for most patients algorithm-based care \"can be given by a trained nurse\".\n\nFor rectal bleeding specifically, the same guidance records that the best current evidence is for sucralfate enemas and hyperbaric oxygen. Endoscopy and surgery in an irradiated pelvis carry extra risk because radiotherapy reduces local blood supply, which the guidance states explicitly.\n\nBowel function after rectal surgery, with or without radiotherapy, is a related but separate problem covered by the glossary entry on low anterior resection syndrome.\n\nWhat comes back, and when: partial, and more than most people are told. Acute bowel symptoms during treatment settle within weeks. Symptoms still present at six months are unlikely to resolve on their own, but several of the underlying diagnoses are treatable, which is the point of the referral. How many people are affected is reported very differently across studies and OnCo has not found a single well-defined cohort figure it is willing to print.",
    principle: "Radiation injures the intestinal crypt epithelium acutely and the submucosal vasculature chronically, producing ischaemia, fibrosis and telangiectasia over years. The resulting symptoms are generated by distinct downstream mechanisms (bile acid loss, bacterial overgrowth, enzyme insufficiency, sphincter injury) that each respond to a specific treatment, so diagnosis rather than symptom suppression is the lever.",
    strengths: ["Randomised evidence that a structured algorithm beats a self-help booklet", "A nurse can deliver it, so it is scalable", "Several of the underlying causes have specific and cheap treatments"],
    limitations: ["Referral pathways from oncology to gastroenterology rarely exist", "Procedures in an irradiated pelvis carry extra risk", "Prevalence figures vary widely between studies"],
    cancers: ["prostate", "cervical", "endometrial", "colorectal", "urothelial"], technologies: ["hyperbaric-oxygen-radiation-injury", "survivorship-care-plan", "imrt-igrt", "oncology-nutrition"], terms: ["late-effects", "low-anterior-resection-syndrome", "living-with-a-stoma-bowel-cancer"], bottlenecks: ["b-survivorship", "b-toxicity-qol"],
    links: [doi("Practice guidance on the management of acute and chronic gastrointestinal problems arising as a result of treatment for cancer (Gut 2012)", "10.1136/gutjnl-2011-300563"), doi("ORBIT: algorithm-based management of gastrointestinal symptoms after pelvic radiation treatment (Lancet 2013)", "10.1016/S0140-6736(13)61648-7"), doi("Defining pelvic-radiation disease for the survivorship era (Lancet Oncol 2010)", "10.1016/S1470-2045(10)70026-7")] }),

  tech({ id: "radiation-skin-recovery", name: "Skin during and after radiotherapy: dressings, steroids and what lasts", sections: [REJ, SUP, "radiation"], status: "established", wikipedia: W("Radiation_dermatitis"), tags: T("strong"),
    tldr: "Skin reactions in the treated area peak around the end of radiotherapy and heal. A thin silicone film applied from the first day cut moderate or severe reactions from 45.6 to 15.5 per cent in a randomised trial in breast cancer, and an international guideline recommends it. Permanent changes, such as fine broken veins and firmness, come later and do not reverse.",
    summary: "The 2023 Multinational Association of Supportive Care in Cancer guideline used a four-round process with 42 international experts and recommended six interventions for prevention: \"photobiomodulation therapy and Mepitel film in people with breast cancer, Hydrofilm, mometasone, betamethasone, and olive oil\", with \"Mepilex Lite dressings\" recommended for management. It also says plainly that \"most interventions were not recommended due to insufficient evidence, conflicting evidence, or lack of consensus to support use\", which is worth knowing before buying a cream.\n\nThe strongest single trial is of the silicone film. In 376 patients with larger breasts after lumpectomy or mastectomy, grade 2 or 3 dermatitis occurred in 15.5 per cent with Mepitel Film against 45.6 per cent with standard care, grade 3 in 2.8 against 13.6 per cent, and moist desquamation in 8.0 against 19.2 per cent. Three patients removed the film early because of rash or itching.\n\nPhotobiomodulation is where the evidence splits, and the split matters in the United Kingdom. The placebo-controlled TRANSDERMIS trial of 120 patients found grade 2 or worse reactions in 6.7 per cent of the laser group against 30 per cent of the placebo group at the end of treatment. The later LABRA trial, in patients receiving the shorter hypofractionated schedule that is now standard in the National Health Service, found 10 per cent against 28 per cent, an 18-point reduction that did not reach significance, and its authors concluded that photobiomodulation \"seems not able to reduce the incidence of severe ARD in breast cancer patients undergoing HF-WBI\". A 2026 guidance statement reaffirms silicone film and hydrofilm, and a separate statement recommends medium-potency topical corticosteroids such as mometasone furoate 0.1 per cent cream for prevention in selected high-risk patients and for early reactions without moist desquamation.\n\nWhat comes back, and when: the acute reaction recovers almost always, over two to six weeks after the last fraction, and skin colour changes fade over months. Late changes are a different thing: telangiectasia, firmness from fibrosis, loss of sweat glands and hair in the field, and altered sensation appear months to years later and are permanent. Hyperbaric oxygen is the treatment with Cochrane-level evidence for late radiation injury at specific sites, and it has its own record.",
    principle: "Radiation kills dividing basal keratinocytes, so the skin surface fails roughly two to three weeks into treatment, when the normal turnover cycle would have replaced them. A film or dressing reduces friction and preserves the moist healing environment, which is why a physical barrier outperforms most creams. Late injury is vascular and fibrotic rather than epithelial, which is why it appears later and does not resolve.",
    strengths: ["A randomised trial with a large effect for a cheap physical barrier", "An international guideline naming exactly what is and is not recommended", "Acute reactions heal in almost everyone"],
    limitations: ["The photobiomodulation evidence is positive in conventional and negative in hypofractionated schedules", "No individual randomised trial numbers verified for topical steroids, only guideline statements", "Late fibrosis and telangiectasia do not reverse"],
    cancers: ["breast-hr-positive", "tnbc", "head-and-neck", "skin-cancer"], technologies: ["photobiomodulation-mucositis", "hyperbaric-oxygen-radiation-injury", "imrt-igrt", "survivorship-care-plan"], terms: ["late-effects"], institutions: ["mascc"], bottlenecks: ["b-toxicity-qol"],
    links: [doi("MASCC clinical practice guidelines for the prevention and management of acute radiation dermatitis (Lancet Oncol 2023)", "10.1016/S1470-2045(23)00067-0"), doi("Mepitel Film for the prevention of acute radiation dermatitis in breast cancer: randomised phase 3 trial (JCO 2023)", "10.1200/JCO.22.01873"), doi("TRANSDERMIS: photobiomodulation to prevent acute radiodermatitis, randomised placebo-controlled trial (Lasers Surg Med 2018)", "10.1002/lsm.22804"), doi("LABRA: photobiomodulation during hypofractionated whole-breast irradiation (Lasers Surg Med 2022)", "10.1002/lsm.23475"), doi("MASCC clinical practice statement: topical corticosteroids for acute radiation dermatitis (Support Care Cancer 2026)", "10.1007/s00520-026-10659-1")] }),

  tech({ id: "nail-changes-after-chemotherapy", name: "Nails after chemotherapy: lifting, ridges and discolouration", sections: [REJ, SUP, "chemotherapy"], status: "emerging", wikipedia: W("Onycholysis"), tags: T("moderate"),
    tldr: "Taxanes lift the nail from its bed, leave transverse ridges that mark each cycle, and discolour it. Reported rates across studies range from none to forty-four per cent. Cooling the hands during the infusion reduced nail damage in a pooled analysis, but the one properly randomised trial was negative and six in ten participants stopped because the cold was too uncomfortable.",
    summary: "The pattern is well described: nail pigmentation, bleeding under the nail, Beau's lines, which are transverse grooves marking each chemotherapy cycle, and onycholysis, the nail separating from its bed. The reference series describing it reviewed the literature and reported an incidence \"ranging from 0% to 44%\", a spread that says more about how it is measured than about how often it happens.\n\nOne pattern is specific and avoidable. In a series of 91 patients given paclitaxel, onycholysis occurred in 5 of 21 who received more than six weekly courses, \"developing in the summer months in all 5 patients\", and in none of those treated every three weeks or in 187 patients given doxorubicin. The authors' conclusion is a piece of practical advice that costs nothing: \"Patients receiving these drugs should protect their nails from sunlight.\"\n\nCooling the hands during the infusion is the main preventive measure and its evidence is mixed. The widely cited frozen-glove study was not randomised: each patient wore the glove on the right hand and the left acted as the control, and onycholysis was grade 0 in 89 per cent of protected hands against 49 per cent of control hands. The randomised trial of the same idea, where the gloved hand was allocated at random, found \"no significant differences\" between hands and had a 60 per cent withdrawal rate \"due to patient discomfort with the intervention\". A meta-analysis pooling three randomised and six prospective studies in 708 patients found total nail toxicity lower with cryotherapy (risk ratio 0.49, 95 per cent confidence interval 0.30 to 0.79), although the confidence interval for grade 2 to 3 toxicity crossed one.\n\nOne thing to avoid: in a randomised trial of 105 women comparing specialist nail drops, nail polish and standard care, \"less nail toxicity was observed in patients receiving specialist nail drops or standard care arms in comparison to those using nail polish\".\n\nWhat comes back, and when: nails grow out, a fingernail taking roughly six months and a toenail twelve to eighteen, so the ridges and discolouration move up the nail and are eventually cut off. OnCo could not find a primary source reporting the proportion in whom nails return to normal, or how long that takes, so that figure is a named gap here rather than a number.",
    principle: "The nail matrix is a rapidly dividing epithelium, so a cytotoxic pulse interrupts plate formation and leaves a groove corresponding in position to the timing of the cycle. Taxanes additionally affect the nail bed vasculature, producing haemorrhage and separation, and photosensitivity explains the weekly-paclitaxel summer pattern. Cooling reduces blood flow and therefore drug delivery to the matrix during the infusion peak.",
    strengths: ["A cheap, specific piece of advice for weekly paclitaxel: keep the nails out of the sun", "Pooled evidence that cooling reduces total nail toxicity", "The damage grows out rather than being structural"],
    limitations: ["The randomised cooling trial was negative and most participants could not tolerate it", "Reported incidence varies from none to forty-four per cent", "No verified figure for how many recover fully, or how long it takes"],
    cancers: ["breast-hr-positive", "tnbc", "prostate", "ovarian"], drugs: ["paclitaxel", "docetaxel", "cabazitaxel"], technologies: ["frozen-gloves-compression-taxane", "scalp-cooling", "cytotoxic-chemotherapy"], terms: ["late-effects"], bottlenecks: ["b-toxicity-qol"],
    links: [doi("Taxane-induced nail changes: incidence, clinical presentation and outcome (Ann Oncol 2003)", "10.1093/annonc/mdg050"), { label: "Onycholysis as a complication of systemic chemotherapy: five cases with prolonged weekly paclitaxel (Cancer 2000)", url: "https://pubmed.ncbi.nlm.nih.gov/10820360/" }, doi("Multicenter study of a frozen glove to prevent docetaxel-induced onycholysis (JCO 2005)", "10.1200/JCO.2005.15.651"), doi("Cryotherapy for docetaxel-induced hand and nail toxicity: randomised controlled trial (Support Care Cancer 2014)", "10.1007/s00520-013-2095-x"), doi("Prophylactic management for taxane-induced nail toxicity: systematic review and meta-analysis (Eur J Cancer Care 2019)", "10.1111/ecc.13118"), doi("Randomised controlled trial of interventions for taxane-induced nail toxicity (Sci Rep 2022)", "10.1038/s41598-022-13327-6")] }),
];

