// LYMPHOEDEMA
// =============================================================================
const lymph: TechnologyInput[] = [
  tech({ id: "lymphoedema-surgery-and-early-detection", name: "Lymphoedema: catching it early, and the operations for it", sections: [REJ, SUP, "surgery"], status: "emerging", wikipedia: W("Lymphedema"), tags: T("moderate"),
    tldr: "Two things have changed. Measuring the limb regularly after surgery, so that a month of compression can start before swelling is obvious, cut progression to full decongestive treatment from 19.2 to 7.9 per cent in a randomised trial. And joining lymphatics to small veins during the node operation cut new lymphoedema from 32 to 9.5 per cent, in a trial not yet finally reported.",
    summary: "Compression and decongestive therapy remain the treatment, and they have their own record. This one covers the two newer ideas, both of which are about getting in earlier.\n\nEarly detection. The PREVENT trial randomised 963 women after breast cancer surgery to surveillance with bioimpedance spectroscopy or with a tape measure. Anyone crossing a threshold received a four-week course of a compression sleeve for twelve hours a day. Bioimpedance triggered that intervention less often (20.1 against 27.5 per cent) and later (median 9.7 against 3.9 months). Among those who triggered, progression to chronic lymphoedema requiring full decongestive physiotherapy occurred in 7.9 per cent of the bioimpedance group against 19.2 per cent of the tape-measure group (relative risk 0.41, 95 per cent confidence interval 0.13 to 0.81, absolute reduction 11.3 points). The earlier interim analysis of the same trial, often quoted, did not reach significance. Several authors and the first author of a later secondary analysis have financial relationships with the device manufacturer, which is worth knowing when reading it.\n\nPrevention at the time of surgery. Immediate lymphatic reconstruction, also called the lymphatic microsurgical preventive healing approach, joins the cut arm lymphatics to a nearby vein during axillary dissection. The randomised trial at Memorial Sloan Kettering reported a preliminary analysis in 2023: cumulative incidence of lymphoedema was 9.5 per cent with reconstruction against 32 per cent without (p=0.014), on 99 patients with twelve-month follow-up out of a planned 174 with twenty-four. The final read-out has not been published, and the supporting meta-analyses are dominated by observational studies whose authors note \"possible publication bias\".\n\nSurgery for established lymphoedema. Lymphaticovenous anastomosis was compared with conservative therapy in a Dutch randomised trial; at six months there was no significant volume reduction in either arm, some quality-of-life domains improved with surgery, and 41 per cent of the surgical group had partly or completely stopped wearing compression against none of the conservative group. A sham-controlled trial is running and has no results. Vascularised lymph node transfer has one randomised trial, of 36 patients, in which limb volume reduction was 57 per cent with transfer plus physiotherapy against 18 per cent with physiotherapy alone. Liposuction for a fibrotic, fat-dominant limb has large non-randomised series showing near-complete volume reduction provided compression is worn continuously afterwards, and no randomised trial in limb lymphoedema at all.\n\nWhat comes back, and when: if it is caught at the stage where a sleeve is enough, most people do not progress. Established lymphoedema is controlled rather than cured; compression is lifelong, and the operations above change volume and garment dependence rather than restoring normal lymphatic drainage. Saying otherwise would be selling something.",
    principle: "Removing or irradiating lymph nodes interrupts drainage; whether a limb swells depends on how much collateral capacity remains. Bioimpedance detects extracellular fluid before volume change is visible, giving a window in which compression can re-establish balance. Lymphaticovenous anastomosis and node transfer create new outflow routes, and liposuction removes the adipose tissue that accumulates once the oedema has been present for years.",
    strengths: ["Randomised evidence that early detection and a short course of compression reduce progression", "A surgical prevention option with a randomised signal at the time of node surgery", "Liposuction reliably reduces volume in long-standing fat-dominant limbs"],
    limitations: ["The prevention trial has not published its final results", "No randomised trial of liposuction in limb lymphoedema exists", "Several key trials have manufacturer involvement or are unblinded"],
    cancers: ["breast-hr-positive", "tnbc", "melanoma", "cervical", "endometrial"], technologies: ["lymphoedema-decongestive-therapy", "sentinel-node", "survivorship-care-plan", "exercise-prescription-after-cancer"], terms: ["breast-cancer-related-lymphoedema", "late-effects"], bottlenecks: ["b-survivorship"], related: ["idea-acc-lymphoedema-prospective-surveillance"],
    links: [doi("PREVENT: bioimpedance spectroscopy or tape measure triggered compression in chronic breast cancer lymphoedema prevention (Lymphat Res Biol 2022)", "10.1089/lrb.2021.0084"), doi("Immediate lymphatic reconstruction to decrease incidence of breast cancer-related lymphoedema: preliminary results of a randomised controlled trial (Ann Surg 2023)", "10.1097/SLA.0000000000005952"), doi("Lymphaticovenous anastomosis versus conservative therapy: six-month interim analysis of a randomised trial (Sci Rep 2024)", "10.1038/s41598-024-52489-3"), doi("A randomised control study of free lymph node transfer for stage II breast cancer-related lymphoedema (Breast Cancer Res Treat 2016)", "10.1007/s10549-016-3716-0"), doi("Liposuction gives complete reduction of chronic large arm lymphoedema after breast cancer (Acta Oncol 2000)", "10.1080/028418600750013195")] }),
];

